-- Run this ONCE after migration_v6.sql. It separates the Prep Team and the
-- Competition Team in the internal portal:
--   * Course Credit and Grading moves into the Competition Team, and the Prep
--     Team gets its own copy.
--   * The two org charts move into their own team's section.
--   * Sections are reordered and the seeded descriptions are refreshed.
-- Anything you have already written or edited is kept. It is safe to run twice.

UPDATE streams SET sort_order = 10 WHERE stream_key = 'prep-team' AND site = 'internal';
UPDATE streams SET sort_order = 11 WHERE stream_key = 'comp-team' AND site = 'internal';
