UPDATE streams SET description = 'How the two teams fit together, and the policies that apply to everyone.' WHERE stream_key = 'how-it-runs' AND site = 'internal' AND description = 'How the Penticton Robotics program is organized: the Prep Team and Competition Team, course credit and grading, org charts, and team policies.';
UPDATE streams SET description = 'Everything for Prep Team students and mentors: onboarding, the learning portal, Google Classroom, the weekly plan, course credit, and how to move up to the Competition Team.' WHERE stream_key = 'prep-team' AND site = 'internal' AND description = 'Resources for Prep Team students and mentors: onboarding, the learning portal, Google Classroom, and how to move up to the Competition Team.';
UPDATE streams SET description = 'Everything for Competition Team students: onboarding, platforms, course credit and daily marks, and the team org chart. Role handbooks sit alongside this section.' WHERE stream_key = 'comp-team' AND site = 'internal' AND description = 'Resources for Competition Team students: onboarding and the platforms the team uses.';

UPDATE units SET stream_id = (SELECT id FROM streams WHERE stream_key = 'comp-team' AND site = 'internal') WHERE title = 'Course Credit and Grading' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'how-it-runs' AND site = 'internal') AND NOT EXISTS (SELECT 1 FROM units x WHERE x.title = 'Course Credit and Grading' AND x.stream_id = (SELECT id FROM streams WHERE stream_key = 'comp-team' AND site = 'internal'));
INSERT INTO units (stream_id, unit_label, title, sort_order, published) SELECT (SELECT id FROM streams WHERE stream_key = 'prep-team' AND site = 'internal'), '', 'Course Credit and Grading', 99, 1 WHERE NOT EXISTS (SELECT 1 FROM units x WHERE x.title = 'Course Credit and Grading' AND x.stream_id = (SELECT id FROM streams WHERE stream_key = 'prep-team' AND site = 'internal'));
INSERT INTO units (stream_id, unit_label, title, sort_order, published) SELECT (SELECT id FROM streams WHERE stream_key = 'prep-team' AND site = 'internal'), '', 'Org Chart', 99, 1 WHERE NOT EXISTS (SELECT 1 FROM units x WHERE x.title = 'Org Chart' AND x.stream_id = (SELECT id FROM streams WHERE stream_key = 'prep-team' AND site = 'internal'));
INSERT INTO units (stream_id, unit_label, title, sort_order, published) SELECT (SELECT id FROM streams WHERE stream_key = 'comp-team' AND site = 'internal'), '', 'Org Chart', 99, 1 WHERE NOT EXISTS (SELECT 1 FROM units x WHERE x.title = 'Org Chart' AND x.stream_id = (SELECT id FROM streams WHERE stream_key = 'comp-team' AND site = 'internal'));
INSERT INTO lessons (unit_id, title, content_html, published, sort_order) SELECT (SELECT id FROM units WHERE title = 'Course Credit and Grading' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'prep-team' AND site = 'internal')), 'Course Credit', '<p>Both the Prep Team and the Competition Team are eligible for Princess Margaret Secondary School course credit. Students can choose whether they would like to officially register and receive graduation credits and a mark on their transcript, or participate without receiving credit. The learning experience is exactly the same either way. The decision to earn credits is entirely up to the student.</p><p>For students wanting a grade and credits, the accredited robotics course is open to students across School District 67. Students attending Summerland Secondary School or Penticton Secondary School are welcome to cross enrol at Princess Margaret.</p>', 1, 1 WHERE NOT EXISTS (SELECT 1 FROM lessons l WHERE l.unit_id = (SELECT id FROM units WHERE title = 'Course Credit and Grading' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'prep-team' AND site = 'internal')) AND l.title = 'Course Credit');
INSERT INTO lessons (unit_id, title, content_html, published, sort_order) SELECT (SELECT id FROM units WHERE title = 'Course Credit and Grading' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'prep-team' AND site = 'internal')), 'Prep Team Grading', '<p><em>Draft. Review and edit before publishing.</em></p><p>Prep Team students are marked on the assignments in their stream. The same criteria are used for every student. The Standardized Plan shows what each assignment is worth.</p><h3>How assignments are marked</h3><ul><li>____</li><li>____</li><li>____</li></ul>', 0, 2 WHERE NOT EXISTS (SELECT 1 FROM lessons l WHERE l.unit_id = (SELECT id FROM units WHERE title = 'Course Credit and Grading' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'prep-team' AND site = 'internal')) AND l.title = 'Prep Team Grading');
UPDATE lessons SET unit_id = (SELECT id FROM units WHERE title = 'Org Chart' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'prep-team' AND site = 'internal')), sort_order = 1 WHERE title = 'Prep Team Org Chart' AND unit_id = (SELECT id FROM units WHERE title = 'Org Charts' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'how-it-runs' AND site = 'internal'));
INSERT INTO lessons (unit_id, title, content_html, published, sort_order) SELECT (SELECT id FROM units WHERE title = 'Org Chart' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'prep-team' AND site = 'internal')), 'Prep Team Org Chart', '', 0, 1 WHERE NOT EXISTS (SELECT 1 FROM lessons l WHERE l.unit_id = (SELECT id FROM units WHERE title = 'Org Chart' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'prep-team' AND site = 'internal')));
UPDATE lessons SET unit_id = (SELECT id FROM units WHERE title = 'Org Chart' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'comp-team' AND site = 'internal')), sort_order = 1 WHERE title = 'Competition Team Org Chart' AND unit_id = (SELECT id FROM units WHERE title = 'Org Charts' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'how-it-runs' AND site = 'internal'));
INSERT INTO lessons (unit_id, title, content_html, published, sort_order) SELECT (SELECT id FROM units WHERE title = 'Org Chart' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'comp-team' AND site = 'internal')), 'Competition Team Org Chart', '', 0, 1 WHERE NOT EXISTS (SELECT 1 FROM lessons l WHERE l.unit_id = (SELECT id FROM units WHERE title = 'Org Chart' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'comp-team' AND site = 'internal')));
DELETE FROM units WHERE title = 'Org Charts' AND stream_id = (SELECT id FROM streams WHERE stream_key = 'how-it-runs' AND site = 'internal') AND NOT EXISTS (SELECT 1 FROM lessons l WHERE l.unit_id = units.id) AND NOT EXISTS (SELECT 1 FROM resources r WHERE r.unit_id = units.id) AND NOT EXISTS (SELECT 1 FROM assignments a WHERE a.unit_id = units.id);
UPDATE lessons SET content_html = '<p>Competition Team students fill in the <strong>Daily Robotics Team Reflection</strong> at the end of each meeting. Your mentors read each one and give the day''s mark after class. That mark feeds the team''s marks sheet and the leaderboard.</p><p><br></p><p><a href="#/reflection">Open the Daily Reflection form</a></p><p><br></p><p>The form asks:</p><ol><li>What did you work on today?</li><li>How productive were you today?</li><li>What mark out of 100 do you believe you deserve for today''s work? (Your own estimate. The mark you receive comes from your mentors.)</li><li>Why do you believe you deserve this mark?</li><li>What is one thing you want to accomplish next time?</li></ol><p><br></p><p>The daily reflections also serve as each Competition Team student''s progress log. Prep Team students are assessed through their stream assignments.</p>' WHERE title = 'Daily Reflection and Progress Log' AND content_html LIKE '%It is the daily self assessment that feeds%';
UPDATE lessons SET content_html = '<p><em>Draft. Review and edit before publishing.</em></p><p>The same four criteria are used for every student, every day. They match the questions in the Daily Robotics Team Reflection.</p><h3>Effort</h3><ul><li>90 to 100: ____</li><li>75 to 89: ____</li><li>60 to 74: ____</li><li>Below 60: ____</li></ul><h3>Productivity</h3><ul><li>90 to 100: ____</li><li>75 to 89: ____</li><li>60 to 74: ____</li><li>Below 60: ____</li></ul><h3>Teamwork</h3><ul><li>90 to 100: ____</li><li>75 to 89: ____</li><li>60 to 74: ____</li><li>Below 60: ____</li></ul><h3>Contribution</h3><ul><li>90 to 100: ____</li><li>75 to 89: ____</li><li>60 to 74: ____</li><li>Below 60: ____</li></ul>' WHERE title = 'Grading Rubric' AND content_html = '<p><em>Draft. Review and edit before publishing.</em></p><p>The same four criteria are used for every student, every day, in both cohorts. They match the questions in the Daily Robotics Team Reflection.</p><h3>Effort</h3><ul><li>90 to 100: ____</li><li>75 to 89: ____</li><li>60 to 74: ____</li><li>Below 60: ____</li></ul><h3>Productivity</h3><ul><li>90 to 100: ____</li><li>75 to 89: ____</li><li>60 to 74: ____</li><li>Below 60: ____</li></ul><h3>Teamwork</h3><ul><li>90 to 100: ____</li><li>75 to 89: ____</li><li>60 to 74: ____</li><li>Below 60: ____</li></ul><h3>Contribution</h3><ul><li>90 to 100: ____</li><li>75 to 89: ____</li><li>60 to 74: ____</li><li>Below 60: ____</li></ul>';
